fn active_root_guidance_uses_cortex_skill_authority() -> anyhow::Result<()> { let root = std::env::var_os("NOOK_REPO_ROOT").map_or_else(|| std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(".."), std::path::PathBuf::from); anyhow::ensure!(!root.join("skills-lock.json").exists(), "external skill registry must remain retired"); let readme = std::fs::read_to_string(root.join("README.md"))?; anyhow::ensure!(readme.contains("Project skill semantics live only in team-owned Markdown under `.cortex`") && readme.contains("task loom:cortex-audit"), "README must route project skill semantics and validation through Cortex and Loom"); for path in ["README.md", "AGENTS.md", ".codex/hooks.json", "CODEX.md", ".cursor/rules.md"] { let content = std::fs::read_to_string(root.join(path))?; for obsolete in [".agents/skills", "task skills:", "task impeccable:", "design-taste-frontend"] { anyhow::ensure!(!content.contains(obsolete), "active authority input {path} references obsolete `{obsolete}` machinery"); } } Ok(()) }
